  `totalEjecutado` decimal(12,2) DEFAULT NULL,
  `saldo` decimal(12,2) DEFAULT NULL,
  `gradoEjecucion` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `procedencia_fondos` json DEFAULT NULL,
  `estado` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rutaTrazadoIndicadores` json DEFAULT NULL,
  `factoresCriticos` json DEFAULT NULL,
  `estructuraProcedencia` json DEFAULT NULL,
  `estaInactiva` tinyint(1) NOT NULL,
  `indicador_pei_id` bigint DEFAULT NULL,
  `objetivo_pei_id` bigint DEFAULT NULL,
  `proceso_id` bigint DEFAULT NULL,
  `producto_oe_id` bigint DEFAULT NULL,
  `proyecto_id` bigint DEFAULT NULL,
  `responsable_id` int DEFAULT NULL,
  `resultado_oe_id` bigint DEFAULT NULL,
  `resultado_og_id` bigint DEFAULT NULL,
  `tipo_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `spme_actividades_act_indicador_pei_id_c7bee3c4_fk_spme_estr` (`indicador_pei_id`),
  KEY `spme_actividades_act_objetivo_pei_id_65673568_fk_spme_estr` (`objetivo_pei_id`),
  KEY `spme_actividades_act_proceso_id_f5c8fc75_fk_spme_estr` (`proceso_id`),
  KEY `spme_actividades_act_producto_oe_id_f819de0e_fk_spme_estr` (`producto_oe_id`),
  KEY `spme_actividades_act_proyecto_id_ca3dc8f2_fk_spme_estr` (`proyecto_id`),
  KEY `spme_actividades_act_responsable_id_5eead2f1_fk_spme_aute` (`responsable_id`),
  KEY `spme_actividades_act_resultado_oe_id_85b8ffa2_fk_spme_estr` (`resultado_oe_id`),
  KEY `spme_actividades_act_resultado_og_id_56e472a1_fk_spme_estr` (`resultado_og_id`),
  KEY `spme_actividades_act_tipo_id_3165ebbd_fk_spme_acti` (`tipo_id`),
  CONSTRAINT `spme_actividades_act_indicador_pei_id_c7bee3c4_fk_spme_estr` FOREIGN KEY (`indicador_pei_id`) REFERENCES `spme_estructuracion_pei_indicadorpeibase` (`id`),
  CONSTRAINT `spme_actividades_act_objetivo_pei_id_65673568_fk_spme_estr` FOREIGN KEY (`objetivo_pei_id`) REFERENCES `spme_estructuracion_pei_objetivopei` (`id`),
  CONSTRAINT `spme_actividades_act_proceso_id_f5c8fc75_fk_spme_estr` FOREIGN KEY (`proceso_id`) REFERENCES `spme_estructuracion_proyecto_proceso` (`id`),
  CONSTRAINT `spme_actividades_act_producto_oe_id_f819de0e_fk_spme_estr` FOREIGN KEY (`producto_oe_id`) REFERENCES `spme_estructuracion_proyecto_productooe` (`productoproyecto_ptr_id`),
  CONSTRAINT `spme_actividades_act_proyecto_id_ca3dc8f2_fk_spme_estr` FOREIGN KEY (`proyecto_id`) REFERENCES `spme_estructuracion_proyecto_proyecto` (`id`),
  CONSTRAINT `spme_actividades_act_responsable_id_5eead2f1_fk_spme_aute` FOREIGN KEY (`responsable_id`) REFERENCES `spme_autenticacion_usuario` (`id`),
  CONSTRAINT `spme_actividades_act_resultado_oe_id_85b8ffa2_fk_spme_estr` FOREIGN KEY (`resultado_oe_id`) REFERENCES `spme_estructuracion_proyecto_resultadooe` (`resultadoproyecto_ptr_id`),
  CONSTRAINT `spme_actividades_act_resultado_og_id_56e472a1_fk_spme_estr` FOREIGN KEY (`resultado_og_id`) REFERENCES `spme_estructuracion_proyecto_resultadoog` (`resultadoproyecto_ptr_id`),
  CONSTRAINT `spme_actividades_act_tipo_id_3165ebbd_fk_spme_acti` FOREIGN KEY (`tipo_id`) REFERENCES `spme_actividades_tipoactividad` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
