INSERT INTO `spme_proyectos_reportes_bitacoraindicadorbase` VALUES (1,'indicadoroe','%',35,NULL,NULL,30.00,'2025-10-20','Durante el trimestre se llevaron a cabo tres activiedas en ellas... y por ello se logro llegar al porcentaje indicado. De los cien niÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±os a los que se ha capacitado en alimentaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n saludable, 30 han reportado cambios significativos en su salud, medidos a travÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©s del sistema peso talla. Se adjunta el reporte de peso y talla realizado el dÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­a... ','[]','2025-10-20 20:43:28.254000','{\"id\": 35, \"tipo\": \"%\", \"codigo\": \"IND01-SPO\", \"baseline\": \"8\", \"redaccion\": \"SMART\", \"target_q1\": \"10\", \"target_q2\": \"15\", \"target_q3\": \"20\", \"definicion\": \"Mide el porcentaje de mejoramiento de los indicadores de salud (Enfermedades No Transmisibles -ENT - Salud Mental - SM) de hombres y mujeres en todas sus edades hasta diciembre del 2026\", \"frecuencia\": \"ANUAL\", \"descripcion\": \"Hasta el aÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±o 2026, mujeres y hombres de todas las edades de las comunidades educativas y de los establecimientos de salud cubiertos por la intervenciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n, con ENT (hipertensiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n, diabetes u obesidad), con trastornos (depresiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n, ansiedad, dependencia de alcohol y sustancias), comorbilidad o factores de riesgo, han mejorado sus indicadores de salud en 20%\", \"responsable\": \"\", \"fechaTargetQ1\": \"2025-03-31\", \"fechaTargetQ2\": \"2025-07-15\", \"fechaTargetQ3\": \"2026-01-15\", \"fechaLineaBase\": \"2024-12-20\", \"target_poblacion\": \"197257\", \"fuente_verificacion\": \"Registros del Sistema de Informacion en salud SNIS (Analisis comparativo 2024-2025-2026)\\nEstudios de evaluacion de medio termino y final del proyecto. \", \"objetivo_especifico\": 21, \"fechaTargetPoblacion\": \"2025-01-01\"}',NULL,58,1),(2,'indicadorroe','1-9',38,NULL,0.00,NULL,'2025-10-20','No hubo avances','[]','2025-10-20 20:51:32.762000','{\"id\": 38, \"tipo\": \"1-9\", \"codigo\": \"IND01-RES01-SPO\", \"baseline\": \"128\", \"redaccion\": \"SMART\", \"target_q1\": \"810\", \"target_q2\": \"1560\", \"target_q3\": \"2362\", \"definicion\": \"Comunidad educativa (Profesores, padres de familia y estudiantes) que desarrollan competencias y motivaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n para promover estilos de vida y ambientes saludables para actuar en la prevenciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n de ENT-SM-VBG-SSR y el manejo de factores de riesgo.\", \"frecuencia\": \"TRIMESTRAL\", \"descripcion\": \"2326 (95%). de profesores/as, padres/madres de familia y estudiantes de comunidades educativas que desarrollan competencias y motivaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n para promover estilos de vida y ambientes saludables para actuar en la prevenciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n de ENT-SM-VBG-SSR y el manejo de factores de riesgo\", \"responsable\": null, \"fechaTargetQ1\": \"2025-03-21\", \"fechaTargetQ2\": \"2025-07-15\", \"fechaTargetQ3\": \"2026-01-15\", \"fechaLineaBase\": \"2024-12-20\", \"target_poblacion\": \"2326\", \"fuente_verificacion\": \"Registros del Proyecto\\nEvaluacion de medio Termino\\nEvaluaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n Final del Proyecto\", \"fechaTargetPoblacion\": \"2024-12-20\"}',NULL,60,1);
